package app.kinnect.live;
import android.app.*;import android.content.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;

/** A single setup surface over the existing Studio camera. */
final class LiveSetupSheet {
 private final FxEngine fx;private final Activity activity;private boolean front;private Dialog dialog;private LiveGamePicker picker;private String mode="chat",game="";private TextView startButton,gameButton;private LinearLayout gameOptions;private final int ink,muted,soft,purple;
 LiveSetupSheet(Activity a,boolean front,FxEngine fx){this.fx=fx;activity=a;this.front=front;int v=WebTheme.isDark(a)?1:0;ink=WebDesign.INK[v];muted=WebDesign.MUTED[v];soft=WebDesign.WASH[v];purple=WebDesign.PURPLE[v];}
 private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 private TextView button(String text,String icon){TextView t=new KinnectText(activity);t.setText(I18n.t(text));t.setTextSize(14);t.setTextColor(ink);t.setGravity(Gravity.CENTER_VERTICAL);t.setMinHeight(dp(50));t.setPadding(dp(12),dp(10),dp(12),dp(10));GradientDrawable b=new GradientDrawable();b.setColor(soft);b.setCornerRadius(dp(14));t.setBackground(b);Drawable d=WebIcons.load(activity,icon);d.setTint(purple);d.setBounds(0,0,dp(22),dp(22));t.setCompoundDrawablesRelative(d,null,null,null);t.setCompoundDrawablePadding(dp(10));return t;}
 private TextView toggle(CheckBox state,String label,String icon){TextView t=button(label,icon);t.setTextSize(12);t.setMinLines(2);t.setEnabled(state.isEnabled());t.setGravity(Gravity.CENTER);Drawable d=t.getCompoundDrawablesRelative()[0];t.setCompoundDrawablesRelative(null,d,null,null);Runnable update=()->{t.setAlpha(state.isChecked()?1f:.5f);t.setSelected(state.isChecked());t.setContentDescription(I18n.t(label)+" · "+I18n.t(state.isChecked()?"Bật":"Tắt"));};t.setOnClickListener(v->{state.setChecked(!state.isChecked());update.run();});update.run();return t;}
 void front(boolean value){front=value;}
 void show(){if(dialog!=null){startButton.setEnabled(true);dialog.show();return;}
  LinearLayout body=new LinearLayout(activity);body.setOrientation(1);body.setTag("live:camera-setup");
  EditText title=new KinnectInput(activity);title.setSingleLine(true);title.setHint(I18n.t("Tiêu đề buổi Live"));title.setTextColor(ink);title.setHintTextColor(muted);title.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(80)});body.addView(title,new LinearLayout.LayoutParams(-1,dp(50)));
  LinearLayout modes=new LinearLayout(activity);modes.setPadding(0,dp(12),0,dp(12));TextView chat=button("Trò chuyện · Miễn phí","video"),games=button("Chơi game · 490 xu","gamepad");LinearLayout.LayoutParams chip=new LinearLayout.LayoutParams(0,-2,1);chip.rightMargin=dp(8);modes.addView(chat,chip);modes.addView(games,new LinearLayout.LayoutParams(0,-2,1));body.addView(modes);
  gameOptions=new LinearLayout(activity);gameOptions.setOrientation(1);gameOptions.setVisibility(View.GONE);gameButton=button("Chọn game","gamepad");gameButton.setOnClickListener(v->{picker=new LiveGamePicker(activity,game,value->{game=value;gameButton.setText(I18n.t(value.isEmpty()?"Chọn game":value));});picker.show();});gameOptions.addView(gameButton,new LinearLayout.LayoutParams(-1,-2));
  CheckBox sound=new CheckBox(activity);sound.setText(I18n.t("Âm thanh game"));sound.setTextColor(ink);sound.setChecked(android.os.Build.VERSION.SDK_INT>=29);sound.setEnabled(android.os.Build.VERSION.SDK_INT>=29);CheckBox comments=new CheckBox(activity);comments.setText(I18n.t("Bình luận nổi"));comments.setTextColor(ink);comments.setChecked(android.provider.Settings.canDrawOverlays(activity));TextView notice=new KinnectText(activity);notice.setText(I18n.t("Phát toàn màn hình, gồm cả thông báo. Dùng Tạm che khi cần."));notice.setTextSize(12);notice.setTextColor(muted);notice.setPadding(0,dp(6),0,dp(10));gameOptions.addView(notice);body.addView(gameOptions);
  CheckBox mic=new CheckBox(activity);mic.setText(I18n.t("Micro"));mic.setTextColor(ink);mic.setChecked(true);LinearLayout toggles=new LinearLayout(activity);toggles.setBaselineAligned(false);TextView micToggle=toggle(mic,"Micro","mic"),soundToggle=toggle(sound,"Tiếng game","volume_2"),commentsToggle=toggle(comments,"Bình luận","message_circle");for(TextView t:new TextView[]{micToggle,soundToggle,commentsToggle}){LinearLayout.LayoutParams slot=new LinearLayout.LayoutParams(0,-2,1);slot.setMargins(dp(3),dp(8),dp(3),0);toggles.addView(t,slot);}body.addView(toggles);
  Runnable update=()->{chat.setAlpha(mode.equals("chat")?1f:.5f);games.setAlpha(mode.equals("game")?1f:.5f);chat.setSelected(mode.equals("chat"));games.setSelected(mode.equals("game"));gameOptions.setVisibility(mode.equals("game")?View.VISIBLE:View.GONE);soundToggle.setVisibility(mode.equals("game")?View.VISIBLE:View.INVISIBLE);commentsToggle.setVisibility(mode.equals("game")?View.VISIBLE:View.INVISIBLE);};chat.setOnClickListener(v->{mode="chat";update.run();});games.setOnClickListener(v->{mode="game";update.run();});update.run();
  TextView start=button("Bắt đầu","video");startButton=start;start.getCompoundDrawablesRelative()[0].setTint(0xffffffff);start.setGravity(Gravity.CENTER);start.setTextColor(0xffffffff);start.setBackgroundTintList(android.content.res.ColorStateList.valueOf(purple));start.setOnClickListener(v->{if(mode.equals("game")&&LiveGameLaunch.intent(activity,game)==null){Toast.makeText(activity,I18n.t(game.isEmpty()?"Hãy chọn game trước.":"Không tìm thấy game trên máy. Hãy cài game hoặc chọn game khác."),Toast.LENGTH_LONG).show();return;}if(mode.equals("game")){LiveGamePass.ensure(activity,()->{if(mode.equals("game")&&LiveGameLaunch.intent(activity,game)==null){Toast.makeText(activity,I18n.t(game.isEmpty()?"Hãy chọn game trước.":"Không tìm thấy game trên máy. Hãy cài game hoặc chọn game khác."),Toast.LENGTH_LONG).show();return;}start.setEnabled(false);dialog.dismiss();activity.startActivity(new Intent(activity,LiveActivity.class).putExtra(LiveActivity.EXTRA_HOST,true).putExtra("cameraSetup",true).putExtra("liveMode",mode).putExtra("gameTitle",game).putExtra("title",title.getText().toString().trim()).putExtra("front",front).putExtra("filter",fx.filter).putExtra("sticker",fx.sticker).putExtra("beauty",fx.beautyOn).putExtra("smooth",fx.smooth).putExtra("blemish",fx.blemish).putExtra("eyes",fx.eyes).putExtra("lips",fx.lips).putExtra("mic",mic.isChecked()).putExtra("sound",sound.isChecked()).putExtra("comments",comments.isChecked()));});}else{if(mode.equals("game")&&LiveGameLaunch.intent(activity,game)==null){Toast.makeText(activity,I18n.t(game.isEmpty()?"Hãy chọn game trước.":"Không tìm thấy game trên máy. Hãy cài game hoặc chọn game khác."),Toast.LENGTH_LONG).show();return;}start.setEnabled(false);dialog.dismiss();activity.startActivity(new Intent(activity,LiveActivity.class).putExtra(LiveActivity.EXTRA_HOST,true).putExtra("cameraSetup",true).putExtra("liveMode",mode).putExtra("gameTitle",game).putExtra("title",title.getText().toString().trim()).putExtra("front",front).putExtra("filter",fx.filter).putExtra("sticker",fx.sticker).putExtra("beauty",fx.beautyOn).putExtra("smooth",fx.smooth).putExtra("blemish",fx.blemish).putExtra("eyes",fx.eyes).putExtra("lips",fx.lips).putExtra("mic",mic.isChecked()).putExtra("sound",sound.isChecked()).putExtra("comments",comments.isChecked()));}});
  ScrollView scroll=new ScrollView(activity){protected void onMeasure(int w,int h){super.onMeasure(w,View.MeasureSpec.makeMeasureSpec(activity.getResources().getDisplayMetrics().heightPixels*55/100,View.MeasureSpec.AT_MOST));}};scroll.addView(body);LinearLayout container=new LinearLayout(activity);container.setOrientation(1);container.addView(scroll);LinearLayout.LayoutParams footer=new LinearLayout.LayoutParams(-1,-2);footer.topMargin=dp(12);container.addView(start,footer);dialog=new Sheet(activity).setTitle(I18n.t("Live")).setView(container).show();start.setTextColor(0xffffffff);dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);
 }
 void close(){if(picker!=null)picker.close();if(dialog!=null)dialog.dismiss();}
}
